Fix a high-severity bug in birdseye's semantic diff. Worktree: `/Users/steve.briggs/projects/operations/.claude/worktrees/birdseye`.

## Working Environment

- Branch: `worktree-birdseye`
- HEAD: `021e400`
- Use absolute paths or `cd` into the worktree.
- **NEVER push.** **NEVER `git add .` / `git add -A`.**

## The Bug (from bugbot)

`blockHash` in `apps/birdseye/internal/diff/semantic.go` only digests the Type + Labels of nested blocks. Their attributes and any further-nested content are NOT included in the hash. So changes inside nested blocks like `lifecycle { prevent_destroy = true → false }`, `dynamic`, `provisioner`, `inline_policy`, etc. are silently lost — `diffMap` reports the parent resource as unchanged when in fact its body has changed.

Current code (lines 184-189):

```go
for _, nested := range blk.Body.Blocks {
    h.Write([]byte(nested.Type))
    h.Write([]byte{0})
    h.Write([]byte(strings.Join(nested.Labels, "|")))
    h.Write([]byte{0})
}
```

## The Fix

Refactor `blockHash` to recurse into nested blocks. Split into a recursive helper that hashes a block's labels + sorted attribute keys + attribute source bytes + recursively-hashed nested blocks.

In `apps/birdseye/internal/diff/semantic.go`:

Replace the existing `blockHash` function (lines 167-191) with:

```go
// blockHash digests the content of a block using actual source bytes for
// attribute expressions, recursing into nested blocks so changes anywhere
// in the block tree (e.g., lifecycle { prevent_destroy = X }, dynamic,
// provisioner) shift the hash.
func blockHash(e blockEntry) string {
	h := sha256.New()
	hashBlock(h, e.block, e.src)
	return hex.EncodeToString(h.Sum(nil))
}

// hashBlock writes a block's labels, sorted attribute key + source text
// pairs, and each nested block's (type, recursive hash) into h.
func hashBlock(h hash.Hash, blk *hclsyntax.Block, src []byte) {
	h.Write([]byte(strings.Join(blk.Labels, "|")))
	h.Write([]byte{0})
	keys := make([]string, 0, len(blk.Body.Attributes))
	for k := range blk.Body.Attributes {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		attr := blk.Body.Attributes[k]
		h.Write([]byte(k))
		h.Write([]byte{0})
		h.Write([]byte(exprText(src, attr.Expr.Range())))
		h.Write([]byte{0})
	}
	for _, nested := range blk.Body.Blocks {
		h.Write([]byte(nested.Type))
		h.Write([]byte{0})
		hashBlock(h, nested, src)
		h.Write([]byte{0})
	}
}
```

Add `"hash"` to the import block (alphabetically with stdlib).

## Regression Tests

Append to `apps/birdseye/internal/diff/semantic_test.go`:

```go
func TestSemanticDetectsNestedBlockAttributeChange(t *testing.T) {
	a := mkArchive(map[string]string{"main.tf": `resource "aws_s3_bucket" "alpha" {
  lifecycle {
    prevent_destroy = true
  }
}`})
	b := mkArchive(map[string]string{"main.tf": `resource "aws_s3_bucket" "alpha" {
  lifecycle {
    prevent_destroy = false
  }
}`})
	changes, err := Semantic(a, b)
	if err != nil {
		t.Fatalf("Semantic: %v", err)
	}
	if !hasChange(changes, "resource", "aws_s3_bucket.alpha", StatusModified) {
		t.Errorf("expected resource modified due to nested lifecycle change:\n%v", changes)
	}
}

func TestSemanticDetectsDeepNestedChange(t *testing.T) {
	a := mkArchive(map[string]string{"main.tf": `resource "aws_iam_role" "alpha" {
  inline_policy {
    name   = "p"
    policy = "old"
  }
}`})
	b := mkArchive(map[string]string{"main.tf": `resource "aws_iam_role" "alpha" {
  inline_policy {
    name   = "p"
    policy = "new"
  }
}`})
	changes, err := Semantic(a, b)
	if err != nil {
		t.Fatalf("Semantic: %v", err)
	}
	if !hasChange(changes, "resource", "aws_iam_role.alpha", StatusModified) {
		t.Errorf("expected resource modified due to deeply nested attribute change:\n%v", changes)
	}
}

func TestSemanticIdenticalNestedBlocksUnchanged(t *testing.T) {
	src := `resource "aws_s3_bucket" "alpha" {
  lifecycle {
    prevent_destroy = true
  }
}`
	a := mkArchive(map[string]string{"main.tf": src})
	b := mkArchive(map[string]string{"main.tf": src})
	changes, err := Semantic(a, b)
	if err != nil {
		t.Fatalf("Semantic: %v", err)
	}
	if len(changes) != 0 {
		t.Errorf("expected no changes for identical nested blocks, got: %v", changes)
	}
}
```

